-- Aquagram — 0053: Tür görselleri 9. parti (269–300 arası 31 tür, 44 görsel; 281 eksik)
-- 284 (thayeria-boehlkei): zipte 284_1.jpg ve 284_1.webp çakışıyordu → 1, 2 ve 284_2 → 3 yapıldı.
update public.species s set images = (select array_agg('https://aquagram.com.tr/media/tur/' || v.slug || '-' || i || '.webp' order by i) from generate_series(1, v.adet) i)
from (values ('hyphessobrycon-pulchripinnis',2),('hyphessobrycon-rosaceus',1),('hyphessobrycon-sweglesi',2),('inpaichthys-kerri',1),('moenkhausia-pittieri',2),('moenkhausia-sanctaefilomenae',2),('nematobrycon-palmeri',1),('paracheirodon-axelrodi',2),('paracheirodon-innesi',1),('paracheirodon-simulans',1),('petitella-rhodostoma',1),('phenacogrammus-interruptus',2),('pristella-maxillaris',1),('psalidodon-anisitsi',1),('thayeria-boehlkei',3),('boraras-brigittae',2),('boraras-maculatus',1),('boraras-merah',2),('boraras-urophthalmoides',2),('danio-aesculapii',1),('danio-choprae',1),('danio-erythromicron',1),('danio-margaritatus',1),('danio-rerio',1),('danio-rerio-var-frankei',2),('danio-tinwini',1),('devario-aequipinnatus',1),('devario-malabaricus',1),('laubuka-dadiburjori',1),('microdevario-kubotai',2),('rasbora-borapetensis',1)) as v(slug, adet)
where s.slug = v.slug;
